package com.ricozknow.enterprise.audit; import com.ricozknow.audit.*; import com.ricozknow.common.TenantContext; import com.ricozknow.common.TenantContext; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/admin/audit-logs") @RequiredArgsConstructor public class AuditAdminController {private final AuditLogRepository repo; @GetMapping @PreAuthorize("hasRole('ADMIN')") public Page<AuditLog> list(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="50") int size){return repo.findByTenantId(TenantContext.get(),PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,200)),Sort.by(Sort.Direction.DESC,"createdAt")));}}
